/**
 * 带重试+退避的导航。Temu 网关（Azure Traffic Manager → gw-sg）会偶发重置连接
 * （ERR_CONNECTION_CLOSED / ERR_NETWORK_CHANGED 等），单次 goto 太脆，这里多试几次。
 * 每次失败后退避递增；中途若已到达目标页则提前成功。
 * @returns {Promise<boolean>} 是否成功导航到目标页
 */
export async function gotoWithRetry(page, url, cfg, { attempts = 5 } = {}) {
  const base = /** @type {string} */ (url).replace(/\/goods\/list.*$/, '/');
  for (let i = 0; i < attempts; i++) {
    if (page.isClosed()) return false;
    try {
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs });
      return true;
    } catch (e) {
      const msg = e.message || String(e);
      log.warn(`导航失败（第 ${i + 1}/${attempts} 次）：${msg.split('\n')[0]}`);
      if (page.isClosed()) return false;
      // 退避：2s,4s,6s,8s…
      await page.waitForTimeout(2000 * (i + 1));
      // 隔一次先访问域名根，绕开偶发对某深链的重置
      if (i % 2 === 1) {
        await page.goto(base, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs }).catch(() => {});
        await page.waitForTimeout(1500);
      }
    }
  }
  return false;
}

