1	import { log } from './logger.js';
2	import { closePopups } from './popups.js';
3	
4	/**
5	 * 抓取单个店铺的监测指标：
6	 *   - onSaleCount        「在售中」商品数量（来自顶部状态标签）
7	 *   - trafficWatchCount  「商品流量待关注」数量（来自快速筛选芯片）
8	 *   - trafficDeclineCount「商品流量近期有下降」数量（来自接口 JSON / 行内徽标）
9	 *   - anomalyItems       尽力枚举的异常商品（标题 / SKC）
10	 *
11	 * 采用「接口拦截 + DOM 兜底」双通道，尽量稳。
12	 */
13	
14	const MARK_WATCH = '商品流量待关注';
15	const MARK_DECLINE = '商品流量近期有下降';
16	const MARK_DECLINE_ALT = ['流量近期有下降', '流量下降', '商品流量待处理'];
17	
18	export async function scanStore(page, storeName, cfg) {
19	  const captured = [];
20	  const onResp = async (resp) => {
21	    try {
22	      const url = resp.url();
23	      if (!/goods|product|list|query|mms|search|page/i.test(url)) return;
24	      const ct = (resp.headers()['content-type'] || '');
25	      if (!ct.includes('json')) return;
26	      const text = await resp.text();
27	      if (!text) return;
28	      if (text.includes('流量') || /skc|goodsList|productList|onSale|itemList/i.test(text)) {
29	        captured.push({ url, text });
30	      }
31	    } catch { /* ignore */ }
32	  };
33	  page.on('response', onResp);
34	
35	  try {
36	    // 确保在商品列表页
37	    if (!/goods\/list/.test(page.url())) {
38	      await page.goto(cfg.goodsListUrl, { waitUntil: 'domcontentloaded' });
39	      await page.waitForTimeout(2500);
40	    }
41	    await closePopups(page);
42	
43	    // 切到「在售中」标签，触发对应列表接口
44	    await clickOnSaleTab(page);
45	    await page.waitForTimeout(2500);
46	
47	    const onSaleCount = await readOnSaleCount(page);
48	    const trafficWatchCount = await readWatchChip(page);
49	    const { declineCount, items } = await readAnomalies(page, captured);
50	
51	    return {
52	      store: storeName,
53	      onSaleCount,
54	      trafficWatchCount,
55	      trafficDeclineCount: declineCount,
56	      trafficAnomalyTotal:
57	        (trafficWatchCount ?? 0) + (declineCount ?? 0),
58	      anomalyItems: items,
59	      capturedApiCount: captured.length,
60	    };
61	  } finally {
62	    page.off('response', onResp);
63	  }
64	}
65	
66	/** 点击「在售中」状态标签 */
67	async function clickOnSaleTab(page) {
68	  const tab = page.getByText(/^在售中\s*\d*/).first();
69	  if (await tab.isVisible({ timeout: 3000 }).catch(() => false)) {
70	    await tab.click({ timeout: 3000 }).catch(() => {});
71	  }
72	}
73	
74	/** 读取「在售中 N」数量 */
75	async function readOnSaleCount(page) {
76	  const loc = page.getByText(/在售中\s*\d+/).first();
77	  const txt = await loc.innerText({ timeout: 3000 }).catch(() => '');
78	  const m = txt.match(/在售中\s*(\d+)/);
79	  return m ? Number(m[1]) : null;
80	}
81	
82	/** 读取快速筛选芯片「商品流量待关注 N」 */
83	async function readWatchChip(page) {
84	  const loc = page.getByText(/商品流量待关注\s*\d+/).first();
85	  const txt = await loc.innerText({ timeout: 2000 }).catch(() => '');
86	  const m = txt.match(/商品流量待关注\s*(\d+)/);
87	  return m ? Number(m[1]) : null;
88	}
89	
90	/**
91	 * 统计「流量异常」商品：优先用接口 JSON 文本计数，DOM 行内徽标兜底并提取商品标识。
92	 */
93	async function readAnomalies(page, captured) {
94	  // 1) 接口 JSON 文本计数（不依赖字段名，直接数标记串出现次数）
95	  let declineFromApi = 0;
96	  for (const { text } of captured) {
97	    declineFromApi += countOccurrences(text, MARK_DECLINE);
98	    for (const alt of MARK_DECLINE_ALT) declineFromApi += countOccurrences(text, alt);
99	  }
100	
101	  // 2) DOM 行内徽标：提取可见的异常商品标识
102	  const items = await extractAnomalyItemsFromDom(page);
103	  const declineFromDom = items.filter((i) => /下降/.test(i.mark)).length;
104	
105	  const declineCount = Math.max(declineFromApi, declineFromDom);
106	  return { declineCount, items };
107	}
108	
109	/** 从当前渲染的行里提取带流量徽标的商品（尽力而为） */
110	async function extractAnomalyItemsFromDom(page) {
111	  const markers = [MARK_WATCH, MARK_DECLINE, ...MARK_DECLINE_ALT];
112	  const out = [];
113	  for (const mark of markers) {
114	    const badges = page.getByText(mark, { exact: false });
115	    const n = Math.min(await badges.count().catch(() => 0), 50);
116	    for (let i = 0; i < n; i++) {
117	      const badge = badges.nth(i);
118	      // 向上找行容器，读 SKC / 标题
119	      const rowText = await badge
120	        .locator('xpath=ancestor::tr[1] | xpath=ancestor::*[contains(@class,"row") or contains(@class,"Row")][1]')
121	        .first()
122	        .innerText()
123	        .catch(() => '');
124	      const skc = (rowText.match(/SKC\s*(?:ID)?[:：]?\s*(\d{6,})/) || [])[1] || '';
125	      const title = (rowText.split('\n').find((l) => l.trim().length > 6) || '').trim().slice(0, 40);
126	      out.push({ mark: mark.replace('商品流量', ''), skc, title });
127	    }
128	  }
129	  // 去重（按 skc+mark）
130	  const seen = new Set();
131	  return out.filter((i) => {
132	    const k = i.skc + '|' + i.mark;
133	    if (seen.has(k)) return false;
134	    seen.add(k);
135	    return true;
136	  });
137	}
138	
139	function countOccurrences(hay, needle) {
140	  if (!hay || !needle) return 0;
141	  let count = 0, idx = 0;
142	  while ((idx = hay.indexOf(needle, idx)) !== -1) { count++; idx += needle.length; }
143	  return count;
144	}
