1	import { writeFileSync } from 'node:fs';
2	import { resolve } from 'node:path';
3	import { ROOT } from './config.js';
4	import { launchBrowser, isLoggedIn } from './browser.js';
5	import { closePopups } from './popups.js';
6	import { log } from './logger.js';
7	
8	/**
9	 * 校准脚本：有头登录态下，抓取商品列表页 & 店铺切换相关的
10	 *   - 所有 XHR/fetch 接口 URL（帮助确定商品列表 API）
11	 *   - 顶部 header / 店铺切换器的 HTML（帮助确定选择器）
12	 * 结果写入 data/calibrate-*.txt，供人工核对后微调选择器。
13	 */
14	export async function calibrate(cfg) {
15	  const { context, page } = await launchBrowser(cfg, { headless: false });
16	  const apiUrls = new Set();
17	  page.on('request', (req) => {
18	    const t = req.resourceType();
19	    if (t === 'xhr' || t === 'fetch') apiUrls.add(`${req.method()} ${req.url()}`);
20	  });
21	
22	  if (!(await isLoggedIn(page, cfg))) {
23	    log.error('未登录，请先 npm run login');
24	    await context.close();
25	    return;
26	  }
27	  await closePopups(page);
28	  log.info('已进入商品列表页，采集接口与 DOM 中…（10 秒）');
29	  await page.waitForTimeout(4000);
30	
31	  // 点一下「在售中」标签，触发列表接口
32	  const tab = page.getByText(/在售中\s*\d*/).first();
33	  await tab.click({ timeout: 3000 }).catch(() => {});
34	  await page.waitForTimeout(4000);
35	
36	  // 保存接口清单
37	  const apiList = [...apiUrls].filter((u) => /goods|product|list|query|mms|mall|shop|search/i.test(u));
38	  writeFileSync(
39	    resolve(ROOT, 'data', 'calibrate-apis.txt'),
40	    [...apiUrls].sort().join('\n'),
41	    'utf8'
42	  );
43	  log.info(`接口清单已保存（${apiUrls.size} 条），疑似相关：`);
44	  for (const u of apiList.slice(0, 40)) log.info('  ', u);
45	
46	  // 保存顶部 header HTML（含店铺切换器）
47	  const headerHtml = await page
48	    .locator('header, [class*="header" i], [class*="Header" i]')
49	    .first()
50	    .innerHTML()
51	    .catch(() => '');
52	  writeFileSync(resolve(ROOT, 'data', 'calibrate-header.html'), headerHtml, 'utf8');
53	
54	  // 保存整页可见文本片段（辅助核对标签/芯片文案）
55	  const bodyText = await page.locator('body').innerText().catch(() => '');
56	  writeFileSync(resolve(ROOT, 'data', 'calibrate-bodytext.txt'), bodyText, 'utf8');
57	
58	  // 保存「切换前」整页 HTML，供离线核对
59	  writeFileSync(
60	    resolve(ROOT, 'data', 'calibrate-page-before.html'),
61	    await page.content().catch(() => ''),
62	    'utf8'
63	  );
64	
65	  // 自动尝试打开店铺切换器：逐个试候选触发区，打开后把整页 HTML 存盘，
66	  // 供离线分析下拉结构（stores.js 的 SWITCHER_TRIGGERS / STORE_ITEM_SELECTORS 据此微调）。
67	  const SWITCHER_CANDIDATES = [
68	    '[class*="MallSelect"]',
69	    '[class*="mall-select"]',
70	    '[class*="shopSelect"]',
71	    '[class*="StoreSelect"]',
72	    '[class*="mallName" i]',
73	    '[class*="shopName" i]',
74	    'header [class*="select" i]',
75	  ];
76	  let openedBy = '';
77	  for (const sel of SWITCHER_CANDIDATES) {
78	    const el = page.locator(sel).first();
79	    if (await el.isVisible({ timeout: 400 }).catch(() => false)) {
80	      await el.click({ timeout: 1500 }).catch(() => {});
81	      await page.waitForTimeout(1200);
82	      openedBy = sel;
83	      break;
84	    }
85	  }
86	  writeFileSync(
87	    resolve(ROOT, 'data', 'calibrate-page-switcher-open.html'),
88	    await page.content().catch(() => ''),
89	    'utf8'
90	  );
91	  writeFileSync(
92	    resolve(ROOT, 'data', 'calibrate-switcher-meta.txt'),
93	    `openedBy=${openedBy || '(未命中任何候选，见下方手动观察)'}\n候选清单:\n${SWITCHER_CANDIDATES.join('\n')}\n`,
94	    'utf8'
95	  );
96	  if (openedBy) log.info(`已自动点开疑似店铺切换器（命中 ${openedBy}），整页 HTML 已存盘。`);
97	  else log.warn('未自动命中店铺切换器候选，请在接下来 20 秒内手动点开，我已存下切换前整页 HTML 供比对。');
98	
99	  log.info('校准文件已写入 data/：calibrate-apis.txt / calibrate-header.html / calibrate-bodytext.txt / calibrate-page-before.html / calibrate-page-switcher-open.html / calibrate-switcher-meta.txt');
